def solve(payload):
    try:
        source = payload.get('source')
        target = payload.get('target')
        value = float(payload.get('value'))
    except (ValueError, KeyError):
        return {
            'valid': False,
            'reason': 'Invalid input format or missing fields'
        }

    # Define valid units
    valid_units = {'C', 'F', 'K', 'Pa', 'kPa', 'bar', 'V', 'mV'}

    if source not in valid_units or target not in valid_units:
        return {
            'valid': False,
            'reason': 'Invalid unit'
        }

    # Group units by category
    unit_to_category = {
        'C': 'temperature',
        'F': 'temperature',
        'K': 'temperature',
        'Pa': 'pressure',
        'kPa': 'pressure',
        'bar': 'pressure',
        'V': 'voltage',
        'mV': 'voltage'
    }

    source_cat = unit_to_category[source]
    target_cat = unit_to_category[target]

    if source_cat != target_cat:
        return {
            'valid': False,
            'reason': 'Units must be in the same category'
        }

    # Conversion logic based on the source and target unit
    if source_cat == 'temperature':
        if source == 'F':
            canonical_value = (value - 32) * 5 / 9
        elif source == 'K':
            canonical_value = value - 273.15
        else:  # 'C'
            canonical_value = value

        if target == 'C':
            result = canonical_value
        elif target == 'F':
            result = canonical_value * 9 / 5 + 32
        elif target == 'K':
            result = canonical_value + 273.15
        else:
            return {'valid': False, 'reason': 'Invalid target unit'}
    elif source_cat == 'pressure':
        if source == 'kPa':
            canonical_value = value * 1000
        elif source == 'bar':
            canonical_value = value * 100000
        else:  # 'Pa'
            canonical_value = value

        if target == 'Pa':
            result = canonical_value
        elif target == 'kPa':
            result = canonical_value / 1000
        elif target == 'bar':
            result = canonical_value / 100000
        else:
            return {'valid': False, 'reason': 'Invalid target unit'}
    elif source_cat == 'voltage':
        if source == 'mV':
            canonical_value = value / 1000
        else:  # 'V'
            canonical_value = value

        if target == 'V':
            result = canonical_value
        elif target == 'mV':
            result = canonical_value * 1000
        else:
            return {'valid': False, 'reason': 'Invalid target unit'}
    else:
        return {'valid': False, 'reason': 'Unknown category'}

    # Round using ROUND_HALF_EVEN (default Python behavior)
    rounded_result = round(result, 2)

    return {
        'valid': True,
        'value': rounded_result,
        'unit': target
    }
